import { execFileSync } from "child_process";
import { realpathSync, statSync, existsSync, mkdirSync, writeFileSync } from "fs";
import { homedir } from "os";
import path from "path";

process.on("uncaughtException", () => process.exit(0));

// Per-machine marker recording that the install notice has been shown once.
// Lives in the user's cache dir so it spans every project and every spec on
// this machine — once installed, the CLI is on PATH for all of them anyway.
function installNoticeMarkerPath() {
  const cacheHome = process.env.XDG_CACHE_HOME || path.join(homedir(), ".cache");
  return path.join(cacheHome, "allium", "cli-install-notice-shown");
}

// Fallback marker in the workspace root, used when the per-machine cache dir
// isn't writable. Scoped to one workspace rather than the whole machine, but
// it still stops the notice from re-firing on every edit.
function projectNoticeMarkerPath(projectRoot) {
  return path.join(projectRoot, ".allium-cli-notice-shown");
}

function markerExists(p) {
  try {
    return existsSync(p);
  } catch {
    return false;
  }
}

function persistMarker(p) {
  try {
    mkdirSync(path.dirname(p), { recursive: true });
    writeFileSync(p, "Allium CLI install notice shown.\n");
    return true;
  } catch {
    return false;
  }
}

function installCommandFor(platform) {
  if (platform === "darwin") {
    return "brew tap juxt/allium && brew install allium   (or: cargo install allium-cli)";
  }
  if (platform === "win32") {
    return "cargo install allium-cli";
  }
  return "cargo install allium-cli   (or, with Homebrew: brew tap juxt/allium && brew install allium)";
}

// On the first .allium edit where the CLI is absent, surface a one-time notice
// instructing the model to offer to install it. Returns the notice text if it
// should be emitted, or null if the user has already been notified.
function installNoticeOnce(projectRoot) {
  const cacheMarker = installNoticeMarkerPath();
  const projectMarker = projectNoticeMarkerPath(projectRoot);

  // If either marker is already present, the user has been notified before.
  if (markerExists(cacheMarker) || markerExists(projectMarker)) return null;

  // Persist the per-machine marker first; if its cache dir isn't writable, fall
  // back to a marker in the workspace root. Knowing which (if any) succeeded
  // lets the notice tell the user, honestly, whether it will recur.
  let savedTo = null;
  if (persistMarker(cacheMarker)) savedTo = "cache";
  else if (persistMarker(projectMarker)) savedTo = "project";

  const command = installCommandFor(process.platform);
  const lines = [
    "Notice from ECA hook `allium.check-spec`:",
    "",
    "Allium CLI not found on PATH — this spec is NOT being formally checked.",
    "",
    "The CLI (`allium check` / `allium analyse`) adds structural verification the",
    "language model can't do reliably alone: tracing data flow across rules, proving",
    "every entity lifecycle can reach a terminal state, and spotting dead ends. With",
    "it installed, every .allium edit is checked and the results feed back into the",
    "conversation, producing more correct and complete specs.",
    "",
    "ACTION: Offer to install it for the user now. If they agree, first check the",
    "relevant package manager exists, then run the command below.",
    "",
    `  Suggested command for this machine (platform: ${process.platform}):`,
    `    ${command}`,
    "  More detail: https://github.com/juxt/allium-tools — make sure the `allium`",
    "  binary ends up on your PATH after installing.",
  ];

  if (savedTo === "cache") {
    lines.push(
      "",
      "This notice fires only once per machine, so do not raise it again afterwards.",
    );
  } else if (savedTo === "project") {
    lines.push(
      "",
      "NOTE: the per-machine marker couldn't be written, so this has been recorded",
      `in the workspace instead (${projectMarker}). The notice won't fire again for`,
      "this workspace; let the user know they may want to add that file to .gitignore.",
    );
  } else {
    // Neither marker could be saved, so the hook can't remember it has notified
    // the user. Be upfront about that and hand off to manual install.
    lines.push(
      "",
      "NOTE: the notice marker could NOT be saved — neither the per-machine cache",
      `nor the workspace root (${projectRoot}) is writable — so this would otherwise`,
      "reappear on every .allium edit. Tell the user this directly, share the manual",
      "install steps above, and ask them to confirm they're happy to install the CLI",
      "themselves. Once they confirm, continue with their task without blocking, and",
      "treat the missing CLI as an acknowledged limitation rather than re-raising it",
      "each edit until the `allium` binary is on PATH.",
    );
  }

  return lines.join("\n");
}

let data = "";
for await (const chunk of process.stdin) {
  data += chunk;
}

let input;
try {
  input = JSON.parse(data);
} catch {
  process.exit(0);
}

// ECA sends { tool_input: { path } } for write_file and edit_file.
const filePath = input.tool_input?.path;

if (typeof filePath !== "string" || path.extname(filePath) !== ".allium") {
  process.exit(0);
}

let resolved;
try {
  resolved = realpathSync(filePath);
  if (!statSync(resolved).isFile()) process.exit(0);
} catch {
  process.exit(0);
}

function workspaceRoots(payload) {
  const payloadRoots = Array.isArray(payload.workspaces) ? payload.workspaces : [];
  const roots = payloadRoots.filter((root) => typeof root === "string" && root.length > 0);
  return roots.length > 0 ? roots : [process.cwd()];
}

// Returns the workspace root containing the file, or null if it's outside all.
function containingWorkspace(file, roots) {
  const resolvedRoots = [];
  for (const root of roots) {
    try {
      resolvedRoots.push(realpathSync(root));
    } catch {
      // Skip unresolvable workspace roots.
    }
  }

  return (
    resolvedRoots.find((root) => file === root || file.startsWith(root + path.sep)) ?? null
  );
}

const projectRoot = containingWorkspace(resolved, workspaceRoots(input));
if (!projectRoot) {
  process.exit(0);
}

try {
  execFileSync("allium", ["check", resolved], {
    encoding: "utf-8",
    stdio: "pipe",
  });
} catch (e) {
  if (e.code === "ENOENT") {
    // The allium binary isn't installed. Show the install notice once (per
    // machine, or per workspace if the cache dir isn't writable) as
    // additional context for the model.
    const notice = installNoticeOnce(projectRoot);
    if (notice) {
      process.stdout.write(JSON.stringify({ additionalContext: notice }));
    }
    process.exit(0);
  }

  const diagnostics = (e.stderr || "") + (e.stdout || "");
  if (diagnostics) {
    const additionalContext = [
      "Automatic Allium validation from ECA hook `allium.check-spec` after editing this `.allium` file.",
      "",
      `The Allium CLI reported diagnostics for ${resolved}:`,
      "",
      diagnostics,
    ].join("\n");

    process.stdout.write(JSON.stringify({ additionalContext }));
  }
  process.exit(0);
}

import { execFileSync } from "child_process";
import { mkdtempSync, mkdirSync, writeFileSync, rmSync, existsSync, chmodSync } from "fs";
import { tmpdir } from "os";
import path from "path";

const hook = new URL("./check-spec.mjs", import.meta.url).pathname;
let passed = 0;
let failed = 0;

function run(input, { env = {}, cwd } = {}) {
  try {
    const stdout = execFileSync(process.execPath, [hook], {
      input: JSON.stringify(input),
      encoding: "utf-8",
      stdio: ["pipe", "pipe", "pipe"],
      env: { ...process.env, ...env },
      ...(cwd ? { cwd } : {}),
    });
    return { status: 0, stdout, stderr: "" };
  } catch (e) {
    return { status: e.status, stdout: e.stdout || "", stderr: e.stderr || "" };
  }
}

function runRaw(rawStdin, { env = {}, cwd } = {}) {
  try {
    const stdout = execFileSync(process.execPath, [hook], {
      input: rawStdin,
      encoding: "utf-8",
      stdio: ["pipe", "pipe", "pipe"],
      env: { ...process.env, ...env },
      ...(cwd ? { cwd } : {}),
    });
    return { status: 0, stdout, stderr: "" };
  } catch (e) {
    return { status: e.status, stdout: e.stdout || "", stderr: e.stderr || "" };
  }
}

function assert(name, actual, expected) {
  if (actual === expected) {
    console.log(`  pass: ${name}`);
    passed++;
  } else {
    console.log(`  FAIL: ${name} (expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)})`);
    failed++;
  }
}

function assertIncludes(name, actual, expectedSubstring) {
  if (actual.includes(expectedSubstring)) {
    console.log(`  pass: ${name}`);
    passed++;
  } else {
    console.log(`  FAIL: ${name} (missing ${JSON.stringify(expectedSubstring)} in ${JSON.stringify(actual)})`);
    failed++;
  }
}

function parseJson(stdout) {
  try {
    return JSON.parse(stdout);
  } catch {
    return null;
  }
}

const root = mkdtempSync(path.join(tmpdir(), "allium-eca-hook-test-"));
const binDir = path.join(root, "bin");
const emptyBinDir = path.join(root, "empty-bin");
const workspaceA = path.join(root, "workspace-a");
const workspaceB = path.join(root, "workspace-b");
const outside = path.join(root, "outside");

mkdirSync(binDir);
mkdirSync(emptyBinDir);
mkdirSync(workspaceA);
mkdirSync(workspaceB);
mkdirSync(outside);

const fakeAllium = path.join(binDir, "allium");
writeFileSync(fakeAllium, "#!/bin/sh\necho \"fake diagnostics for $2\" >&2\nexit 1\n", { mode: 0o755 });

const validA = path.join(workspaceA, "spec.allium");
const validB = path.join(workspaceB, "spec.allium");
const outsideFile = path.join(outside, "spec.allium");
const markdownFile = path.join(workspaceA, "README.md");

writeFileSync(validA, "-- allium: 3\n");
writeFileSync(validB, "-- allium: 3\n");
writeFileSync(outsideFile, "-- allium: 3\n");
writeFileSync(markdownFile, "# Not Allium\n");

const fakeEnv = { PATH: binDir };
const missingCliEnv = { PATH: emptyBinDir };

console.log("ECA hook — early exits:\n");

assert(
  "missing tool_input.path skipped",
  run({ tool_input: {} }, { env: fakeEnv, cwd: workspaceA }).stdout,
  "",
);

assert(
  "non-.allium file skipped",
  run({ tool_input: { path: markdownFile }, workspaces: [workspaceA] }, { env: fakeEnv }).stdout,
  "",
);

assert(
  "non-existent .allium file skipped",
  run({ tool_input: { path: path.join(workspaceA, "ghost.allium") }, workspaces: [workspaceA] }, { env: fakeEnv }).stdout,
  "",
);

assert(
  "malformed JSON exits cleanly",
  runRaw("{not json}", { env: fakeEnv, cwd: workspaceA }).status,
  0,
);

assert(
  "empty stdin exits cleanly",
  runRaw("", { env: fakeEnv, cwd: workspaceA }).status,
  0,
);

console.log("\nECA hook — CLI handling:\n");

const invalidResult = run({ tool_input: { path: validA }, workspaces: [workspaceA] }, { env: fakeEnv });
const invalidJson = parseJson(invalidResult.stdout);

assert("invalid file hook exits successfully", invalidResult.status, 0);
assert("invalid file returns JSON", invalidJson !== null, true);
assertIncludes(
  "diagnostics identify ECA hook",
  invalidJson?.additionalContext || "",
  "Automatic Allium validation from ECA hook `allium.check-spec`",
);
assertIncludes(
  "diagnostics include fake checker output",
  invalidJson?.additionalContext || "",
  "fake diagnostics for",
);

console.log("\nECA hook — workspace boundaries:\n");

assert(
  "file outside workspace skipped",
  run({ tool_input: { path: outsideFile }, workspaces: [workspaceA] }, { env: fakeEnv }).stdout,
  "",
);

const secondWorkspaceResult = run(
  { tool_input: { path: validB }, workspaces: [workspaceA, workspaceB] },
  { env: fakeEnv },
);
assert("file in second workspace accepted", parseJson(secondWorkspaceResult.stdout) !== null, true);

const fallbackCwdResult = run(
  { tool_input: { path: validA } },
  { env: fakeEnv, cwd: workspaceA },
);
assert("missing workspaces falls back to cwd", parseJson(fallbackCwdResult.stdout) !== null, true);

// --- CLI missing: one-time install notice ---
// Force the "binary not found" path by running with a PATH that contains no
// allium, and an isolated XDG_CACHE_HOME so the per-machine marker is hermetic.

console.log("\nECA hook — CLI missing, one-time install notice:\n");

function noticeOf(result) {
  return parseJson(result.stdout)?.additionalContext || "";
}

const noticeCache = mkdtempSync(path.join(tmpdir(), "allium-eca-hook-cache-"));
const noticeEnv = { ...missingCliEnv, XDG_CACHE_HOME: noticeCache };

const firstNotice = run({ tool_input: { path: validA }, workspaces: [workspaceA] }, { env: noticeEnv });
assert("first edit with no CLI exits cleanly", firstNotice.status, 0);
assert(
  "first edit surfaces notice as additionalContext",
  /install/i.test(noticeOf(firstNotice)),
  true,
);
assert(
  "notice carries a concrete install command",
  /cargo install allium-cli/.test(noticeOf(firstNotice)),
  true,
);
assert(
  "notice identifies the ECA hook",
  noticeOf(firstNotice).includes("allium.check-spec"),
  true,
);
assert(
  "persisted notice promises it fires only once",
  /only once per machine/.test(noticeOf(firstNotice)),
  true,
);

const secondNotice = run({ tool_input: { path: validA }, workspaces: [workspaceA] }, { env: noticeEnv });
assert("notice fires only once (subsequent edits emit nothing)", secondNotice.stdout, "");

// A fresh cache (e.g. another machine) shows the notice again.
const freshCache = mkdtempSync(path.join(tmpdir(), "allium-eca-hook-cache-"));
const freshNotice = run(
  { tool_input: { path: validA }, workspaces: [workspaceA] },
  { env: { ...missingCliEnv, XDG_CACHE_HOME: freshCache } },
);
assert("notice shows again under a fresh cache", /install/i.test(noticeOf(freshNotice)), true);

// Scope: the notice must NOT leak onto non-spec or out-of-workspace edits even
// when the CLI is absent — those exit early, before the checker is invoked.
const scopeCache = mkdtempSync(path.join(tmpdir(), "allium-eca-hook-cache-"));
const scopeEnv = { ...missingCliEnv, XDG_CACHE_HOME: scopeCache };

assert(
  "no notice on non-.allium edit when CLI absent",
  run({ tool_input: { path: markdownFile }, workspaces: [workspaceA] }, { env: scopeEnv }).stdout,
  "",
);
assert(
  "no notice on out-of-workspace .allium edit when CLI absent",
  run({ tool_input: { path: outsideFile }, workspaces: [workspaceA] }, { env: scopeEnv }).stdout,
  "",
);

// A blocked cache: XDG_CACHE_HOME points at a file, so the per-machine marker
// can't be written. Shared by the fallback and both-unwritable scenarios.
const blockedRoot = mkdtempSync(path.join(tmpdir(), "allium-eca-hook-blocked-"));
const blockedCache = path.join(blockedRoot, "not-a-dir");
writeFileSync(blockedCache, "x\n");

// Fallback: cache unwritable but workspace root writable → the marker falls
// back to .allium-cli-notice-shown in the workspace root, so the notice still
// fires only once (per workspace) and doesn't crash.
const fallbackWorkspace = mkdtempSync(path.join(tmpdir(), "allium-eca-hook-fallback-"));
const fallbackFile = path.join(fallbackWorkspace, "spec.allium");
writeFileSync(fallbackFile, "-- allium: 3\n");
const fallbackEnv = { ...missingCliEnv, XDG_CACHE_HOME: blockedCache };

const fb1 = run({ tool_input: { path: fallbackFile }, workspaces: [fallbackWorkspace] }, { env: fallbackEnv });
assert("notice shown when cache unwritable, via workspace fallback", /install/i.test(noticeOf(fb1)), true);
assert(
  "fallback notice names the workspace marker file",
  /\.allium-cli-notice-shown/.test(noticeOf(fb1)),
  true,
);
assert(
  "fallback notice does not claim per-machine once-only",
  /only once per machine/.test(noticeOf(fb1)),
  false,
);
assert(
  "workspace fallback marker file is actually created",
  existsSync(path.join(fallbackWorkspace, ".allium-cli-notice-shown")),
  true,
);
const fb2 = run({ tool_input: { path: fallbackFile }, workspaces: [fallbackWorkspace] }, { env: fallbackEnv });
assert("workspace fallback marker suppresses re-firing", fb2.stdout, "");

// Both unwritable: cache blocked AND workspace root read-only → no marker can
// be persisted, so the hook hands off to manual install and keeps re-firing.
// (Skipped under root, which bypasses directory permissions.)
const roWorkspace = mkdtempSync(path.join(tmpdir(), "allium-eca-hook-rows-"));
const roFile = path.join(roWorkspace, "spec.allium");
writeFileSync(roFile, "-- allium: 3\n");
chmodSync(roWorkspace, 0o500);
const runningAsRoot = typeof process.getuid === "function" && process.getuid() === 0;
if (!runningAsRoot) {
  const roEnv = { ...missingCliEnv, XDG_CACHE_HOME: blockedCache };
  const ro1 = run({ tool_input: { path: roFile }, workspaces: [roWorkspace] }, { env: roEnv });
  assert(
    "both-unwritable notice tells the user it couldn't be saved",
    /could NOT be saved/.test(noticeOf(ro1)),
    true,
  );
  assert(
    "both-unwritable notice asks the user to confirm self-install",
    /confirm they're happy/.test(noticeOf(ro1)),
    true,
  );
  const ro2 = run({ tool_input: { path: roFile }, workspaces: [roWorkspace] }, { env: roEnv });
  assert("both-unwritable notice re-fires", /install/i.test(noticeOf(ro2)), true);
}
chmodSync(roWorkspace, 0o700);

rmSync(noticeCache, { recursive: true, force: true });
rmSync(freshCache, { recursive: true, force: true });
rmSync(scopeCache, { recursive: true, force: true });
rmSync(blockedRoot, { recursive: true, force: true });
rmSync(fallbackWorkspace, { recursive: true, force: true });
rmSync(roWorkspace, { recursive: true, force: true });
rmSync(root, { recursive: true, force: true });

console.log(`\n${passed} passed, ${failed} failed`);
process.exit(failed > 0 ? 1 : 0);

{
  "allium.check-spec": {
    "type": "postToolCall",
    "matcher":
    {"eca__write_file": {"argsMatchers": { "path": [".*\\.allium$"]}},
     "eca__edit_file": {"argsMatchers": { "path": [".*\\.allium$"]}}},
    "visible": true,
    "actions": [
      {
        "type": "shell",
        "shell": "node \"${plugin:root}/hooks/check-spec.mjs\""
      }
    ]
  },
  "allium.loop-trace-pre": {
    "type": "preToolCall",
    "matcher": "eca__spawn_agent",
    "visible": false,
    "actions": [
      {
        "type": "shell",
        "shell": "node \"${plugin:root}/hooks/loop-trace.mjs\" pre"
      }
    ]
  },
  "allium.loop-trace-post": {
    "type": "postToolCall",
    "matcher": "eca__spawn_agent",
    "visible": false,
    "actions": [
      {
        "type": "shell",
        "shell": "node \"${plugin:root}/hooks/loop-trace.mjs\" post"
      }
    ]
  }
}

// Records real per-subagent-call timing into the Allium loop's trace.
//
// Registered twice in hooks.json, matched to ECA's subagent tool:
//   preToolCall  → node loop-trace.mjs pre    (stamp the call's start)
//   postToolCall → node loop-trace.mjs post   (write duration on return)
//
// Timing has to be captured outside the model — a subagent call isn't a shell
// call the model can wrap in `date`, and the model can't read its own latency.
// A hook fires on the tool events, so it can. It writes one line per call to
// .allium-loop/timings.jsonl; the loop folds those durations into its trace and
// report (driving-the-loop §13). The model's trajectory + routing telemetry is
// the cross-harness baseline; this hook is the deterministic timing layer.
//
// It only records while a loop is active (a .allium-loop/ dir exists), never
// blocks a call (always exits 0), and swallows its own errors.

import {
  closeSync,
  constants,
  existsSync,
  lstatSync,
  openSync,
  readFileSync,
  realpathSync,
  writeFileSync,
} from "fs";
import path from "path";

process.on("uncaughtException", () => process.exit(0));

const event = process.argv[2]; // "pre" | "post"
if (event !== "pre" && event !== "post") process.exit(0);

let data = "";
for await (const chunk of process.stdin) data += chunk;

let input;
try {
  input = JSON.parse(data);
} catch {
  process.exit(0);
}

// The subagent's name is the useful label ("weed", "distill"). ECA sends
// { tool_input: { agent, task } } for eca__spawn_agent; fall back to the tool
// name if the agent field is missing.
const toolInput = input.tool_input ?? {};
const agent = toolInput.agent ?? input.tool_name ?? input.tool ?? "subagent";

// A correlation id pairs a pre with its post. If the harness doesn't provide
// one, fall back to FIFO, which is correct for the sequential phase calls the
// loop makes (a documented limitation under parallel calls).
const corrId = input.tool_call_id ?? input.toolCallId ?? toolInput.id ?? null;

// Resolve the workspace root the same way the check-spec hook does: ECA sends
// the workspace roots in the payload's `workspaces` array.
const payloadRoots = Array.isArray(input.workspaces) ? input.workspaces : [];
const roots = payloadRoots.filter((r) => typeof r === "string" && r.length > 0);
if (roots.length === 0) roots.push(process.cwd());

let projectRoot = null;
for (const r of roots) {
  try {
    const resolved = realpathSync(r);
    // Prefer the first root that has an active loop; else first resolvable.
    if (existsSync(path.join(resolved, ".allium-loop"))) {
      projectRoot = resolved;
      break;
    }
    if (!projectRoot) projectRoot = resolved;
  } catch {
    // try the next root
  }
}
if (!projectRoot) process.exit(0);

// Only trace while a loop is running; otherwise this is an unrelated subagent.
const loopDir = path.join(projectRoot, ".allium-loop");
if (!existsSync(loopDir)) process.exit(0);
try {
  const stat = lstatSync(loopDir);
  if (!stat.isDirectory() || stat.isSymbolicLink()) process.exit(0);
} catch {
  process.exit(0);
}

const pendingPath = path.join(loopDir, ".timing-pending.json");
const timingsPath = path.join(loopDir, "timings.jsonl");
const now = Date.now();

function readPending() {
  try {
    const stat = lstatSync(pendingPath);
    if (!stat.isFile() || stat.isSymbolicLink()) return { byId: {}, fifo: [] };
    const p = JSON.parse(readFileSync(pendingPath, "utf-8"));
    return { byId: p.byId ?? {}, fifo: Array.isArray(p.fifo) ? p.fifo : [] };
  } catch {
    return { byId: {}, fifo: [] };
  }
}
function writeWithoutFollowingSymlinks(filePath, data, append = false) {
  let fd;
  try {
    const noFollow = constants.O_NOFOLLOW ?? 0;
    const mode = append ? constants.O_APPEND : constants.O_TRUNC;
    fd = openSync(filePath, constants.O_WRONLY | constants.O_CREAT | mode | noFollow, 0o600);
    writeFileSync(fd, data);
    return true;
  } catch {
    return false;
  } finally {
    if (fd !== undefined) {
      try {
        closeSync(fd);
      } catch {
        // best-effort
      }
    }
  }
}
function writePending(p) {
  writeWithoutFollowingSymlinks(pendingPath, JSON.stringify(p));
}

if (event === "pre") {
  const p = readPending();
  if (corrId) p.byId[corrId] = { start: now, agent };
  else p.fifo.push({ start: now, agent });
  writePending(p);
  process.exit(0);
}

// event === "post"
const p = readPending();
let rec = null;
if (corrId && p.byId[corrId]) {
  rec = p.byId[corrId];
  delete p.byId[corrId];
} else if (p.fifo.length > 0) {
  rec = p.fifo.shift();
}
writePending(p);

if (rec) {
  const line =
    JSON.stringify({
      ts: new Date(now).toISOString(),
      agent: rec.agent,
      duration_ms: now - rec.start,
    }) + "\n";
  writeWithoutFollowingSymlinks(timingsPath, line, true);
}
process.exit(0);

import { execFileSync } from "child_process";
import { mkdtempSync, mkdirSync, readFileSync, existsSync, rmSync, symlinkSync, writeFileSync } from "fs";
import path from "path";
import { tmpdir } from "os";

const hook = new URL("./loop-trace.mjs", import.meta.url).pathname;
let passed = 0;
let failed = 0;

function assert(name, cond) {
  if (cond) { console.log(`  pass: ${name}`); passed++; }
  else { console.log(`  FAIL: ${name}`); failed++; }
}

// Run the hook once (one event) with a synthetic ECA payload.
function runHook(event, input) {
  try {
    execFileSync("node", [hook, event], {
      input: JSON.stringify(input),
      encoding: "utf-8",
      stdio: ["pipe", "pipe", "pipe"],
    });
  } catch {
    // the hook always exits 0; ignore
  }
}

function newProject({ withLoopDir }) {
  const dir = mkdtempSync(path.join(tmpdir(), "allium-timing-"));
  if (withLoopDir) mkdirSync(path.join(dir, ".allium-loop"));
  return dir;
}
function timings(dir) {
  const p = path.join(dir, ".allium-loop", "timings.jsonl");
  if (!existsSync(p)) return [];
  return readFileSync(p, "utf-8").trim().split("\n").filter(Boolean).map((l) => JSON.parse(l));
}

console.log("\n── loop-trace hook ──\n");

// 1. pre + post with a correlation id → one timing line, right agent, numeric duration.
{
  const dir = newProject({ withLoopDir: true });
  const payload = { tool_call_id: "abc", tool_name: "eca__spawn_agent", tool_input: { agent: "weed" }, workspaces: [dir] };
  runHook("pre", payload);
  runHook("post", payload);
  const t = timings(dir);
  assert("records one timing for a paired pre/post", t.length === 1);
  assert("labels the timing with the agent name", t[0]?.agent === "weed");
  assert("duration is a non-negative number", typeof t[0]?.duration_ms === "number" && t[0].duration_ms >= 0);
  rmSync(dir, { recursive: true, force: true });
}

// 2. No .allium-loop dir → no-op, nothing written.
{
  const dir = newProject({ withLoopDir: false });
  const payload = { tool_call_id: "x", tool_name: "eca__spawn_agent", tool_input: { agent: "weed" }, workspaces: [dir] };
  runHook("pre", payload);
  runHook("post", payload);
  assert("does nothing when no loop is active", !existsSync(path.join(dir, ".allium-loop", "timings.jsonl")));
  rmSync(dir, { recursive: true, force: true });
}

// 3. FIFO fallback when there is no correlation id: two calls pair in order.
{
  const dir = newProject({ withLoopDir: true });
  runHook("pre", { tool_name: "eca__spawn_agent", tool_input: { agent: "distill" }, workspaces: [dir] });
  runHook("pre", { tool_name: "eca__spawn_agent", tool_input: { agent: "propagate" }, workspaces: [dir] });
  runHook("post", { tool_name: "eca__spawn_agent", tool_input: {}, workspaces: [dir] });
  runHook("post", { tool_name: "eca__spawn_agent", tool_input: {}, workspaces: [dir] });
  const t = timings(dir);
  assert("pairs two unkeyed calls in FIFO order", t.length === 2 && t[0].agent === "distill" && t[1].agent === "propagate");
  rmSync(dir, { recursive: true, force: true });
}

// 4. A post with no matching pre writes nothing and does not crash.
{
  const dir = newProject({ withLoopDir: true });
  runHook("post", { tool_call_id: "orphan", tool_name: "eca__spawn_agent", tool_input: { agent: "weed" }, workspaces: [dir] });
  assert("ignores an unpaired post", timings(dir).length === 0);
  rmSync(dir, { recursive: true, force: true });
}

// 5. Malformed stdin is swallowed (no crash, no output).
{
  const dir = newProject({ withLoopDir: true });
  try {
    execFileSync("node", [hook, "pre"], { input: "not json", encoding: "utf-8", stdio: ["pipe", "pipe", "pipe"] });
    assert("survives malformed input", true);
  } catch {
    assert("survives malformed input", false);
  }
  rmSync(dir, { recursive: true, force: true });
}

// 6. Picks the workspace root that has an active loop when several are sent.
{
  const idle = newProject({ withLoopDir: false });
  const active = newProject({ withLoopDir: true });
  const payload = { tool_call_id: "multi", tool_name: "eca__spawn_agent", tool_input: { agent: "tend" }, workspaces: [idle, active] };
  runHook("pre", payload);
  runHook("post", payload);
  assert("routes the timing to the workspace with the loop", timings(active).length === 1);
  rmSync(idle, { recursive: true, force: true });
  rmSync(active, { recursive: true, force: true });
}

// 7. A repository-controlled .allium-loop symlink must not redirect writes.
{
  const dir = newProject({ withLoopDir: false });
  const outside = mkdtempSync(path.join(tmpdir(), "allium-timing-outside-"));
  symlinkSync(outside, path.join(dir, ".allium-loop"));
  const payload = { tool_call_id: "linked-dir", tool_name: "eca__spawn_agent", tool_input: { agent: "weed" }, workspaces: [dir] };
  runHook("pre", payload);
  assert("refuses a symlinked loop directory", !existsSync(path.join(outside, ".timing-pending.json")));
  rmSync(dir, { recursive: true, force: true });
  rmSync(outside, { recursive: true, force: true });
}

// 8. A symlinked pending-state file must not be read or overwritten.
{
  const dir = newProject({ withLoopDir: true });
  const victim = path.join(dir, "victim-pending.txt");
  writeFileSync(victim, "unchanged");
  symlinkSync(victim, path.join(dir, ".allium-loop", ".timing-pending.json"));
  runHook("pre", { tool_call_id: "linked-pending", tool_name: "eca__spawn_agent", tool_input: { agent: "weed" }, workspaces: [dir] });
  assert("refuses a symlinked pending-state file", readFileSync(victim, "utf-8") === "unchanged");
  rmSync(dir, { recursive: true, force: true });
}

// 9. A symlinked timing log must not receive appended data.
{
  const dir = newProject({ withLoopDir: true });
  const payload = { tool_call_id: "linked-log", tool_name: "eca__spawn_agent", tool_input: { agent: "weed" }, workspaces: [dir] };
  runHook("pre", payload);
  const victim = path.join(dir, "victim-timings.txt");
  writeFileSync(victim, "unchanged");
  symlinkSync(victim, path.join(dir, ".allium-loop", "timings.jsonl"));
  runHook("post", payload);
  assert("refuses a symlinked timing log", readFileSync(victim, "utf-8") === "unchanged");
  rmSync(dir, { recursive: true, force: true });
}

console.log(`\n${passed} passed, ${failed} failed`);
process.exit(failed > 0 ? 1 : 0);

